    if not s:
        return ""

    result = []
    count = 1
    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(f"{count}{current_char}")
            current_char = s[i]
            count = 1

    result.append(f"{count}{current_char}")
    return "".join(result)


def rle_decode(s: str) -> str:
    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Parse the number (count)
        num_str = []
        while i < n and s[i].isdigit():
            num_str.append(s[i])
            i += 1

        count = int("".join(num_str))

        # Next character is the character to repeat
        if i < n:
            char = s[i]
            i += 1
            result.append(char * count)

    return "".join(result)
