def flatten(d: dict, sep: str='.') -> dict:
    """
    Flattens a nested dictionary into a single-level dictionary with joined keys.

    - Empty nested dicts are kept as values.
    - Lists are left as values.
    - Non-empty nested dicts are recursively flattened.
    """
    result = {}

    def _flatten(current_dict, prefix=''):
        for key, value in current_dict.items():
            new_key = f"{prefix}{sep}{key}" if prefix else key

            if isinstance(value, dict):
                if len(value) == 0:
                    # Empty nested dicts are kept as values
                    result[new_key] = value
                else:
                    # Recursively flatten non-empty nested dicts
                    _flatten(value, new_key)
            elif isinstance(value, list):
                # Lists are left as values
                result[new_key] = value
            else:
                result[new_key] = value

    _flatten(d)
    return result
