        self._stock = {}

    def add(self, sku: str, qty: int):
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")
        if sku in self._stock:
            self._stock[sku] += qty
        else:
            self._stock[sku] = qty

    def remove(self, sku: str, qty: int):
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")
        if sku not in self._stock:
            raise ValueError(f"SKU {sku} not found in inventory")
        if self._stock[sku] - qty < 0:
            raise ValueError("Remove operation would result in negative stock")
        self._stock[sku] -= qty
        if self._stock[sku] == 0:
            del self._stock[sku]

    def count(self, sku) -> int:
        return self._stock.get(sku, 0)

    def low_stock(self, threshold) -> list[str]:
        return sorted([sku for sku, qty in self._stock.items() if qty < threshold])
