def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not xs:
        return []

    # Sort by start time
    xs_sorted = sorted(xs, key=lambda x: x[0])

    merged = [xs_sorted[0]]

    for start, end in xs_sorted[1:]:
        last_start, last_end = merged[-1]

        # If intervals overlap or touch, merge them
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
