def merge_intervals(xs: list[tuple[int,int]]) -> list[tuple[int,int]]:
    if not xs:
        return []
    intervals = sorted(xs, key=lambda x: x[0])
    merged = [intervals[0]]
    for curr in intervals[1:]:
        last = merged[-1]
        if curr[0] <= last[1]:
            merged[-1] = (last[0], max(last[1], curr[1]))
        else:
            merged.append(curr)
    return merged
